package oop.assigment_problems;
public class LibraryMembershipBoundary {static class LibraryMember{private String name,memberId;private int booksIssued;LibraryMember(String n,String id,int b){name=n;memberId=id;booksIssued=b;}String getName(){return name;}String getMemberId(){return memberId;}int getBooksIssued(){return booksIssued;}}public static void main(String[]a){LibraryMember one=new LibraryMember("Ravi","L1",2),two=new LibraryMember("Anitha","L2",4);System.out.println(one.getName()+" "+one.getMemberId()+" "+one.getBooksIssued());System.out.println(two.getName()+" "+two.getMemberId()+" "+two.getBooksIssued());}}